formulaOrCode:
Patch(
    Requests,
    selectedRequest,
    {
        AssignedTo: {
            '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
            Claims: "i:0#.f|membership|" & Lower(cmbAssignedTo.Selected.Mail),
            DisplayName: cmbAssignedTo.Selected.DisplayName,
            Email: cmbAssignedTo.Selected.Mail,
            Department: "",
            JobTitle: "",
            Picture: ""
        }
    }
)

// Combo box that feeds the Patch
// Items
Office365Users.SearchUserV2({ searchTerm: cmbAssignedTo.SearchText, top: 10, isSearchTermRequired: true }).value
// DisplayFields: ["DisplayName", "Mail"]     SearchFields: ["DisplayName"]     SelectMultiple: false

// Assign to the signed-in user
Patch(Requests, selectedRequest, {
    AssignedTo: {
        '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
        Claims: "i:0#.f|membership|" & Lower(User().Email),
        DisplayName: User().FullName,
        Email: User().Email,
        Department: "", JobTitle: "", Picture: ""
    }
})

// Clear the person field
Patch(Requests, selectedRequest, { AssignedTo: Blank() })

// Guard against an empty selection
If(IsBlank(cmbAssignedTo.Selected.Mail),
   Notify("Choose a person first", NotificationType.Error),
   Select(btnSaveAssignee))        // hidden button that holds the Patch shown at the top

Patch(
    Requests,
    selectedRequest,
    {
        Status: { Value: ddStatus.Selected.Value }
    }
)

// Dropdown bound to the column's own choices
// ddStatus.Items
Choices(Requests.Status)
// ddStatus default when editing (classic dropdown takes the text value)
selectedRequest.Status.Value

// Patch the selected choice record directly (works when Items is Choices())
Patch(Requests, selectedRequest, { Status: ddStatus.Selected })

// Patch a fixed value
Patch(Requests, selectedRequest, { Status: { Value: "In progress" } })

// Radio buttons or a custom list of text values
Patch(Requests, selectedRequest, { Status: { Value: rdoStatus.Selected.Value } })

// Clear the choice
Patch(Requests, selectedRequest, { Status: Blank() })

// Filter on a choice column (delegable)
Filter(Requests, Status.Value = "In progress")

Patch(
    Requests,
    selectedRequest,
    {
        Department: {
            Id: cmbDepartment.Selected.ID,
            Value: cmbDepartment.Selected.Title
        }
    }
)

// Combo box that lists the lookup's source list
// cmbDepartment.Items
Filter(Departments, IsActive = true)
// or the column's own options:  Choices(Requests.Department)   (then use .Id and .Value)

// When Items is Choices(), pass the selection straight through
Patch(Requests, selectedRequest, { Department: cmbDepartment.Selected })

// Default when editing
// cmbDepartment.DefaultSelectedItems
If(IsBlank(selectedRequest.Department.Id), Blank(), LookUp(Departments, ID = selectedRequest.Department.Id))

// Clear the lookup
Patch(Requests, selectedRequest, { Department: Blank() })

// Read other columns from the linked item
LookUp(Departments, ID = ThisItem.Department.Id).ManagerEmail

// Filter by lookup (delegable on Id)
Filter(Requests, Department.Id = cmbDepartment.Selected.ID)

Patch(
    Requests,
    selectedRequest,
    {
        ChecklistJson: JSON(colChecklist, JSONFormat.Compact)
    }
)

// Keep only the columns worth saving
Patch(
    Requests,
    selectedRequest,
    {
        ChecklistJson: JSON(
            ShowColumns(colChecklist, Title, IsComplete, SortOrder),
            JSONFormat.Compact
        )
    }
)

// Guard against the column's size limit before saving
With(
    { payload: JSON(ShowColumns(colChecklist, Title, IsComplete, SortOrder), JSONFormat.Compact) },
    If(
        Len(payload) > 60000,
        Notify("Too many rows to save in one field. Remove some rows.", NotificationType.Error),
        Patch(Requests, selectedRequest, { ChecklistJson: payload })
    )
)

// Save an empty list as an empty array, not blank
Patch(Requests, selectedRequest, { ChecklistJson: If(IsEmpty(colChecklist), "[]", JSON(colChecklist, JSONFormat.Compact)) })

// SharePoint column: Multiple lines of text, Plain text, with "Allow unlimited length" off unless needed.

ClearCollect(
    colChecklist,
    ForAll(
        ParseJSON(selectedRequest.ChecklistJson),
        {
            Title: Text(ThisRecord.Value.Title),
            IsComplete: Boolean(ThisRecord.Value.IsComplete),
            SortOrder: Value(ThisRecord.Value.SortOrder)
        }
    )
)

// Handle an empty or missing value
ClearCollect(
    colChecklist,
    If(
        IsBlank(selectedRequest.ChecklistJson),
        Table(),                                   // nothing saved yet
        ForAll(
            ParseJSON(selectedRequest.ChecklistJson),
            {
                Title: Text(ThisRecord.Value.Title),
                IsComplete: Boolean(ThisRecord.Value.IsComplete),
                SortOrder: Value(ThisRecord.Value.SortOrder)
            }
        )
    )
)

// Typed parsing (where user-defined types are enabled): no per-field conversion needed
// App.Formulas
ChecklistRow := Type({ Title: Text, IsComplete: Boolean, SortOrder: Number });
// then
ClearCollect(colChecklist, ParseJSON(selectedRequest.ChecklistJson, Type([ChecklistRow])))

// Dates saved in JSON come back as ISO text
DateTimeValue(Text(ThisRecord.Value.DueDate))

// Catch malformed JSON
IfError(
    ClearCollect(colChecklist, ForAll(ParseJSON(selectedRequest.ChecklistJson), { Title: Text(ThisRecord.Value.Title) })),
    Notify("The saved checklist could not be read.", NotificationType.Error); Clear(colChecklist)
)

If(
    FormRequest.Valid && FormDetails.Valid,
    SubmitForm(FormRequest);
    SubmitForm(FormDetails),
    Notify("Please fix the highlighted fields before submitting.", NotificationType.Error)
)

// Both forms edit the SAME item: validate both, then save once with Patch
If(
    FormRequest.Valid && FormDetails.Valid,
    IfError(
        Set(selectedRequest,
            Patch(Requests, Coalesce(selectedRequest, Defaults(Requests)), FormRequest.Updates, FormDetails.Updates)
        );
        Notify("Saved", NotificationType.Success),
        Notify("Could not save: " & FirstError.Message, NotificationType.Error)
    ),
    // show each form's own validation messages
    SubmitForm(FormRequest); SubmitForm(FormDetails)
)

// Forms on DIFFERENT lists: save the parent first, then the child from OnSuccess
// btnSave.OnSelect
If(FormRequest.Valid && FormDetails.Valid, SubmitForm(FormRequest), Notify("Fix the highlighted fields", NotificationType.Error))
// FormRequest.OnSuccess
Set(selectedRequest, FormRequest.LastSubmit); SubmitForm(FormDetails)
// FormDetails: the RequestId data card's Update = selectedRequest.ID
// FormDetails.OnSuccess
Notify("Request and details saved", NotificationType.Success); Navigate(scrHome)
// Either form's OnFailure
Notify(Self.Error, NotificationType.Error)

Set(
    selectedRequest,
    Patch(Requests, selectedRequest, { Title: txtTitle.Value })
);
Refresh(Requests);
Set(selectedRequest, LookUp(Requests, ID = selectedRequest.ID))

// Usually enough: Patch returns the saved record, including columns SharePoint calculated
Set(selectedRequest, Patch(Requests, selectedRequest, { Title: txtTitle.Value }))
// No Refresh needed. Galleries bound to Requests update themselves.

// When a flow changes the item after the save, re-read it once the flow has finished
Set(selectedRequest, LookUp(Requests, ID = selectedRequest.ID))

// With an edit form
// frmRequest.OnSuccess
Set(selectedRequest, frmRequest.LastSubmit)

// Keep a local collection in step
Patch(colRequests, LookUp(colRequests, ID = selectedRequest.ID), selectedRequest)

// Handle failure so the variable is not replaced by an error
IfError(
    Set(selectedRequest, Patch(Requests, selectedRequest, { Title: txtTitle.Value })),
    Notify("Save failed: " & FirstError.Message, NotificationType.Error)
)

DefaultSelectedItems =
If(
    IsBlank(selectedRequest.AssignedTo),
    Blank(),
    [selectedRequest.AssignedTo]
)

// Single choice column
// DefaultSelectedItems
If(IsBlank(selectedRequest.Status), Blank(), [selectedRequest.Status])
// Items: Choices(Requests.Status)

// Multi-choice or multi-person column: already a table
selectedRequest.ImpactAreas
selectedRequest.Reviewers

// Lookup column
If(IsBlank(selectedRequest.Department.Id), Blank(),
   Filter(Choices(Requests.Department), Id = selectedRequest.Department.Id))

// People picker fed by Office365Users.SearchUserV2: build a record with the same field names as Items
If(
    IsBlank(selectedRequest.AssignedTo.Email),
    Blank(),
    Table({
        DisplayName: selectedRequest.AssignedTo.DisplayName,
        Mail: selectedRequest.AssignedTo.Email
    })
)

// Text values (Items is ["Low", "Medium", "High"])
If(IsBlank(selectedRequest.PriorityText), Blank(), [selectedRequest.PriorityText])

// New record default
If(IsBlank(selectedRequest), [{ Value: "Normal" }], [selectedRequest.Priority])

Set(
    currentUserRole,
    LookUp(AppSecurity, Lower(Email) = Lower(User().Email), Role.Value)
);

btnApprove.Visible = currentUserRole in ["Admin", "Approver"]

// Security list: AppSecurity with Email (text), Role (Choice), IsActive (Yes/No)

// App.Formulas alternative: evaluated once, cannot be overwritten
nfUserEmail = Lower(User().Email);
nfUserRole  = LookUp(AppSecurity, Email = nfUserEmail && IsActive = true).Role.Value;
nfIsAdmin   = nfUserRole = "Admin";
nfCanApprove = nfUserRole in ["Admin", "Approver"];

// Usage
btnApprove.Visible     : nfCanApprove
btnDelete.DisplayMode  : If(nfIsAdmin, DisplayMode.Edit, DisplayMode.Disabled)
scrAdmin.OnVisible     : If(!nfIsAdmin, Navigate(scrHome))

// A user with several roles: one row per role
ClearCollect(colMyRoles, Filter(AppSecurity, Email = nfUserEmail && IsActive = true));
btnApprove.Visible : "Approver" in colMyRoles.Role.Value

// Default when the user is not in the list
Coalesce(nfUserRole, "Reader")

// Store emails in lower case in the list so the comparison stays delegable
// (Lower() on the column inside LookUp is not delegable).

Filter(
    Requests,
    Status.Value = ddStatus.Selected.Value &&
    StartsWith(Title, txtSearch.Value)
)

// Delegable with SharePoint
//   =, <>, <, >, <=, >= on text, number, date         &&, ||, !
//   StartsWith(column, text)                           choice.Value = "x"
//   person.Email = "x"                                 lookup.Id = n
//   Sort / SortByColumns on simple columns
// Not delegable with SharePoint
//   Search(), in, exactin, EndsWith, Len, Left, Lower/Upper on a column, IsBlank on some types,
//   CountRows / Sum on the list, Distinct, AddColumns, anything on multi-value columns

// Capture values first, then filter
With(
    { email: Lower(User().Email), today: Today() },
    Filter(Requests, AssignedTo.Email = email && DueDate >= today && Status.Value <> "Closed")
)

// Sort on the server
SortByColumns(Filter(Requests, Status.Value = ddStatus.Selected.Value), "Created", SortOrder.Descending)

// Need a non-delegable step? Narrow with a delegable filter first, then work on the small result
With(
    { open: Filter(Requests, Status.Value = "Open") },
    Search(open, txtSearch.Value, "Title", "Description")
)

// Test your formulas: Settings > General > Data row limit = 1, and see what goes missing.

Patch(
    Requests,
    selectedRequest,
    {
        RequestStatus: { Value: "Approved" }
    }
)

// Approve with the supporting fields in one call
IfError(
    Set(selectedRequest,
        Patch(Requests, selectedRequest, {
            RequestStatus:  { Value: "Approved" },
            DecisionDate:   Now(),
            DecisionBy:     User().Email,
            DecisionComments: txtComments.Value
        })
    );
    Notify("Request approved", NotificationType.Success),
    Notify("Could not update the status: " & FirstError.Message, NotificationType.Error)
)

// Only allow the change from the right starting status
If(
    selectedRequest.RequestStatus.Value <> "Submitted",
    Notify("Only submitted requests can be approved.", NotificationType.Warning),
    Patch(Requests, selectedRequest, { RequestStatus: { Value: "Approved" } })
)

// Reject needs a reason
If(IsBlank(Trim(txtComments.Value)),
   Notify("Add a reason for rejecting", NotificationType.Error),
   Patch(Requests, selectedRequest, { RequestStatus: { Value: "Rejected" }, DecisionComments: txtComments.Value }))

// Keep status names in one place
// App.Formulas:  nfStatus = { Draft: "Draft", Submitted: "Submitted", Approved: "Approved", Rejected: "Rejected" };
Patch(Requests, selectedRequest, { RequestStatus: { Value: nfStatus.Approved } })

Set(varEditingRequest, ThisItem);
Set(varShowEditModal, true);
EditForm(frmRequestQuickEdit)

// Overlay container (conEditModal)
// Visible : varShowEditModal
// Inside: a dark rectangle covering the screen (Fill RGBA(0,0,0,0.5)), then a white panel with the form

// frmRequestQuickEdit
// DataSource : Requests
// Item       : varEditingRequest

// Save button
SubmitForm(frmRequestQuickEdit)

// frmRequestQuickEdit.OnSuccess
Set(varEditingRequest, Self.LastSubmit);
Set(varShowEditModal, false);
Notify("Changes saved", NotificationType.Success)

// frmRequestQuickEdit.OnFailure
Notify(Self.Error, NotificationType.Error)

// Cancel button and the X icon
ResetForm(frmRequestQuickEdit);
Set(varShowEditModal, false)

// New item in the same modal
Set(varEditingRequest, Blank());
NewForm(frmRequestQuickEdit);
Set(varShowEditModal, true)

// Heading
If(frmRequestQuickEdit.Mode = FormMode.New, "New request", "Edit " & varEditingRequest.Title)

// Calculate totals from the current gallery or filtered collection
ClearCollect(
    colVisibleRequests,
    galRequests.AllItems
);
Set(varTotalAmount, Sum(colVisibleRequests, Amount));
Set(varOpenCount, CountRows(Filter(colVisibleRequests, Status.Value <> "Complete")));
Set(varHighPriorityCount, CountRows(Filter(colVisibleRequests, Priority.Value = "High")));

// Use labels:
// Text(varTotalAmount, "$#,##0.00")
// varOpenCount & " open requests"

// Without variables: labels that recalculate by themselves
// lblTotal.Text
Text(Sum(galRequests.AllItems, Amount), "$#,##0.00")
// lblCount.Text
CountRows(galRequests.AllItems) & " requests"
// lblAverage.Text
Text(Average(galRequests.AllItems, Amount), "$#,##0.00")

// Line totals from inputs inside the gallery (txtQty and txtPrice in each row)
Sum(galLines.AllItems, Value(txtQty.Text) * Value(txtPrice.Text))

// Totals by group
AddColumns(
    GroupBy(colVisibleRequests, StatusText, Rows),
    Total, Sum(Rows, Amount),
    Items, CountRows(Rows)
)
// (add StatusText first: AddColumns(colVisibleRequests, StatusText, Status.Value))

// Only checked rows
Sum(Filter(galRequests.AllItems, chkSelect.Value), Amount)

// Large lists: AllItems holds only the rows loaded so far.
// Collect the filtered set first, or calculate the total in a flow or a SharePoint view total.

ForAll(
    colChecklist,
    Patch(
        ChecklistItems,
        Coalesce(LookUp(ChecklistItems, ID = ThisRecord.ID), Defaults(ChecklistItems)),
        {
            Title: ThisRecord.Title,
            IsComplete: ThisRecord.IsComplete,
            RequestId: selectedRequest.ID
        }
    )
)

// Faster: one Patch call for the whole table instead of one per row
// New rows (no ID yet)
Patch(
    ChecklistItems,
    ForAll(
        Filter(colChecklist, IsBlank(ID)) As R,
        { Title: R.Title, IsComplete: R.IsComplete, RequestId: selectedRequest.ID }
    )
);
// Existing rows (include the ID so Patch knows which row to update)
Patch(
    ChecklistItems,
    ForAll(
        Filter(colChecklist, !IsBlank(ID)) As R,
        { ID: R.ID, Title: R.Title, IsComplete: R.IsComplete }
    )
);

// Remove rows the user deleted in the app
RemoveIf(ChecklistItems, RequestId = selectedRequest.ID && !(ID in colChecklist.ID));

// Reload so new rows pick up their IDs
ClearCollect(colChecklist, Filter(ChecklistItems, RequestId = selectedRequest.ID));

// Wrap the save
// Put the Patch calls above inside IfError( ... ) as its first argument, then:
//   Notify("Some checklist items were not saved: " & FirstError.Message, NotificationType.Error),
//   Notify("Checklist saved", NotificationType.Success)

With(
    {
        totalRows: CountRows(colChecklist),
        doneRows: CountRows(Filter(colChecklist, IsComplete))
    },
    Patch(
        Deliverables,
        selectedDeliverable,
        { CompletionPercent: If(totalRows = 0, 0, Round(doneRows / totalRows * 100, 0)) }
    )
)

{
  "$schema": "https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json",
  "elmType": "a",
  "txtContent": "Open link",
  "attributes": {
    "href": "@currentField",
    "target": "_blank"
  }
}

Show the link's description as the text, and nothing when the field is empty:

{
  "$schema": "https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json",
  "elmType": "a",
  "txtContent": "=if(@currentField.desc == '', 'Open link', @currentField.desc)",
  "attributes": {
    "href": "@currentField",
    "target": "_blank",
    "rel": "noopener noreferrer",
    "class": "ms-fontColor-themePrimary ms-fontColor-themeDark--hover"
  },
  "style": {
    "display": "=if(@currentField == '', 'none', 'inline-block')",
    "text-decoration": "none"
  }
}

Button style with an icon:

{
  "$schema": "https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json",
  "elmType": "a",
  "attributes": { "href": "@currentField", "target": "_blank", "class": "ms-bgColor-themePrimary ms-fontColor-white" },
  "style": { "padding": "4px 12px", "border-radius": "4px", "text-decoration": "none", "display": "=if(@currentField == '', 'none', 'inline-flex')", "align-items": "center" },
  "children": [
    { "elmType": "span", "attributes": { "iconName": "OpenInNewWindow" }, "style": { "padding-right": "6px" } },
    { "elmType": "span", "txtContent": "Open" }
  ]
}

Build a link from another column (for example a ticket number in a text column):
  "href": "='https://support.contoso.com/tickets/' + [$TicketNumber]"

Append to array variable:
{
  "Name": @{items('Apply_to_each_attachment')?['DisplayName']},
  "ContentBytes": @{body('Get_attachment_content')}
}

Full sequence

1. Initialize variable   varAttachments (Array)   value: []
     (at the top level of the flow, before any loop)

2. Get attachments (SharePoint)
     Site, List, Id : @{triggerBody()?['ID']}

3. Apply to each: @{body('Get_attachments')}       (Settings > Concurrency control: off)
     Get attachment content
       Id              : @{triggerBody()?['ID']}
       File Identifier : @{items('Apply_to_each_attachment')?['Id']}
     Append to array variable (varAttachments)
       {
         "Name": "@{items('Apply_to_each_attachment')?['DisplayName']}",
         "ContentBytes": @{body('Get_attachment_content')}
       }
     Note: Name is text, so it is in quotes. ContentBytes is an object, so it is NOT in quotes.

4. Send an email (V2)
     Attachments : click the small "T" icon to switch to the whole array, then
                   @{variables('varAttachments')}

No attachments on the item
  The loop runs zero times and the email is sent with none. To require one:
  Condition: length(body('Get_attachments')) is equal to 0 -> notify the requester and Terminate.

Without a variable (keeps concurrency on): use a Select
  From : body('Get_attachments')
  Map  : Name -> item()?['DisplayName'], Link -> item()?['AbsoluteUri']
  and put links in the email body instead of attaching the files.

Patch(
    Requests,
    selectedRequest,
    {
        ImpactAreas: ForAll(
            cmbImpactAreas.SelectedItems,
            { Value: Value }
        )
    }
)

// Combo box
// Items                : Choices(Requests.ImpactAreas)
// SelectMultiple       : true
// DefaultSelectedItems : selectedRequest.ImpactAreas

// When Items is Choices(), the selection already has the right shape
Patch(Requests, selectedRequest, { ImpactAreas: cmbImpactAreas.SelectedItems })

// Fixed values
Patch(Requests, selectedRequest, { ImpactAreas: Table({ Value: "Finance" }, { Value: "Operations" }) })

// From a gallery of checkboxes backed by a collection
Patch(Requests, selectedRequest, { ImpactAreas: ForAll(Filter(colAreas, IsChecked), { Value: Name }) })

// Clear all values
Patch(Requests, selectedRequest, { ImpactAreas: Table() })

// Add one value without losing the others
Patch(Requests, selectedRequest, {
    ImpactAreas: Ungroup(Table({ T: selectedRequest.ImpactAreas }, { T: Table({ Value: "Legal" }) }), T)
})

// Display as text
Concat(ThisItem.ImpactAreas, Value, ", ")

// Does it contain a value?
"Finance" in ThisItem.ImpactAreas.Value

Patch(
    Requests,
    selectedRequest,
    {
        Reviewers: ForAll(
            cmbReviewers.SelectedItems,
            {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(Mail),
                DisplayName: DisplayName,
                Email: Mail,
                Department: "",
                JobTitle: "",
                Picture: ""
            }
        )
    }
)

// Combo box
// Items                : Office365Users.SearchUserV2({ searchTerm: cmbReviewers.SearchText, top: 10, isSearchTermRequired: true }).value
// SelectMultiple       : true
// DisplayFields        : ["DisplayName", "Mail"]
// DefaultSelectedItems : ForAll(selectedRequest.Reviewers, { DisplayName: DisplayName, Mail: Email })

// Skip anyone without a mailbox
ForAll(
    Filter(cmbReviewers.SelectedItems, !IsBlank(Mail)) As U,
    {
        '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
        Claims: "i:0#.f|membership|" & Lower(U.Mail),
        DisplayName: U.DisplayName,
        Email: U.Mail,
        Department: "", JobTitle: "", Picture: ""
    }
)

// Clear everyone
Patch(Requests, selectedRequest, { Reviewers: Table() })

// Add the current user to the existing reviewers
Patch(Requests, selectedRequest, {
    Reviewers: Ungroup(
        Table(
            { T: selectedRequest.Reviewers },
            { T: Table({ '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                         Claims: "i:0#.f|membership|" & Lower(User().Email), DisplayName: User().FullName,
                         Email: User().Email, Department: "", JobTitle: "", Picture: "" }) }
        ), T)
})

// Display and email
Concat(ThisItem.Reviewers, DisplayName, ", ")
Concat(ThisItem.Reviewers, Email, ";")

Set(
    savedRequest,
    Patch(Requests, Defaults(Requests), { Title: txtTitle.Value })
);

ForAll(
    colTaskTemplates,
    Patch(
        RequestTasks,
        Defaults(RequestTasks),
        {
            Title: ThisRecord.Title,
            RequestId: savedRequest.ID,
            Status: { Value: "Not Started" }
        }
    )
)

// Complete submit with a busy flag, one bulk write and error handling
If(
    !varSaving,
    Set(varSaving, true);
    IfError(
        // 1. parent
        Set(savedRequest, Patch(Requests, Defaults(Requests), { Title: txtTitle.Value }));
        // 2. children in a single call
        Patch(
            RequestTasks,
            ForAll(
                colTaskTemplates As T,
                {
                    Title: T.Title,
                    RequestId: savedRequest.ID,
                    Status: { Value: "Not Started" },
                    DueDate: DateAdd(Today(), Coalesce(T.DueInDays, 7), TimeUnit.Days)
                }
            )
        );
        Notify("Request " & savedRequest.ID & " created with " & CountRows(colTaskTemplates) & " tasks", NotificationType.Success);
        Navigate(scrRequestDetail),
        // failure
        Notify("Save failed: " & FirstError.Message, NotificationType.Error)
    );
    Set(varSaving, false)
)

// If the parent saved but the tasks did not, offer a retry that only creates the tasks
If(!IsBlank(savedRequest.ID) && IsEmpty(Filter(RequestTasks, RequestId = savedRequest.ID)),
   Notify("The request was saved but its tasks were not. Press Retry tasks.", NotificationType.Warning))

// RequestId: a Number column, indexed. Simpler to write in bulk than a lookup column.

Patch(
    Requests,
    ThisItem,
    {
        IsArchived: true,
        ArchivedOn: Now(),
        ArchivedBy: User().Email
    }
)

// Confirm, then archive, with an undo
// Delete icon OnSelect
UpdateContext({ locConfirmArchive: true, locTarget: ThisItem })

// Confirm button OnSelect
IfError(
    Patch(Requests, LookUp(Requests, ID = locTarget.ID), {
        IsArchived: true, ArchivedOn: Now(), ArchivedBy: User().Email
    });
    UpdateContext({ locConfirmArchive: false, locLastArchivedId: locTarget.ID });
    Notify("Request archived", NotificationType.Success),
    Notify("Could not archive: " & FirstError.Message, NotificationType.Error)
)

// Undo link
Patch(Requests, LookUp(Requests, ID = locLastArchivedId), { IsArchived: false, ArchivedOn: Blank(), ArchivedBy: Blank() })

// Galleries: exclude archived rows (delegable; set the column default to No so no blanks exist)
Filter(Requests, IsArchived = false)

// Admin "Archived" view with restore
Filter(Requests, IsArchived = true)
// Restore button
Patch(Requests, ThisItem, { IsArchived: false })

// Also exclude archived items elsewhere
// SharePoint views : IsArchived is equal to No
// Flows            : Filter Query  IsArchived eq 0

// Permanent delete after a retention period: a scheduled flow
//   Get items: IsArchived eq 1 and ArchivedOn lt '@{addDays(utcNow(), -365)}'  ->  Delete item

IfError(
    Patch(Requests, selectedRequest, { Title: txtTitle.Value }),
    Notify("The request could not be saved. Please check required fields and try again.", NotificationType.Error),
    Notify("Request saved.", NotificationType.Success)
)

// Show SharePoint's own message, keep the saved record, and only navigate on success
IfError(
    Set(selectedRequest, Patch(Requests, selectedRequest, { Title: txtTitle.Value }));
    Notify("Request saved.", NotificationType.Success);
    Navigate(scrRequestDetail),
    Notify("Could not save: " & FirstError.Message, NotificationType.Error)
)

// Different messages for different failures
IfError(
    Patch(Requests, selectedRequest, { Title: txtTitle.Value }),
    Switch(
        FirstError.Kind,
        ErrorKind.Conflict,              Notify("Someone else changed this request. Refresh and try again.", NotificationType.Warning),
        ErrorKind.InsufficientPermissions, Notify("You do not have permission to edit this request.", NotificationType.Error),
        ErrorKind.Network,               Notify("No connection. Check your network and try again.", NotificationType.Error),
        ErrorKind.Validation,            Notify("A required field is missing: " & FirstError.Message, NotificationType.Error),
        Notify("Could not save: " & FirstError.Message, NotificationType.Error)
    )
)

// Catch anything not handled locally: App.OnError
Notify("Something went wrong: " & FirstError.Message, NotificationType.Error);
Trace("Unhandled error", TraceSeverity.Error, { Message: FirstError.Message, Source: FirstError.Source, Observed: FirstError.Observed })

// Older alternative: check the data source after the call
Patch(Requests, selectedRequest, { Title: txtTitle.Value });
If(!IsEmpty(Errors(Requests)), Notify(First(Errors(Requests)).Message, NotificationType.Error))

Filter(
    Requests,
    DueDate >= dpStart.SelectedDate &&
    DueDate < DateAdd(dpEnd.SelectedDate, 1, TimeUnit.Days)
)

// Date pickers left empty should not filter anything out
With(
    {
        fromDate: Coalesce(dpStart.SelectedDate, Date(2000, 1, 1)),
        toDate:   DateAdd(Coalesce(dpEnd.SelectedDate, Date(2100, 1, 1)), 1, TimeUnit.Days)
    },
    SortByColumns(
        Filter(Requests, DueDate >= fromDate && DueDate < toDate),
        "DueDate", SortOrder.Ascending
    )
)

// Common ranges (calculate the boundary first, outside the Filter)
// Today
With({ s: Today(), e: DateAdd(Today(), 1, TimeUnit.Days) }, Filter(Requests, DueDate >= s && DueDate < e))
// This week (Monday to Sunday)
With({ s: DateAdd(Today(), -(Weekday(Today(), StartOfWeek.Monday) - 1), TimeUnit.Days) },
     Filter(Requests, DueDate >= s && DueDate < DateAdd(s, 7, TimeUnit.Days)))
// This month
With({ s: Date(Year(Today()), Month(Today()), 1) },
     Filter(Requests, DueDate >= s && DueDate < DateAdd(s, 1, TimeUnit.Months)))
// Last 30 days
With({ s: DateAdd(Today(), -30, TimeUnit.Days) }, Filter(Requests, Created >= s))
// Overdue and still open
With({ t: Today() }, Filter(Requests, DueDate < t && Status.Value <> "Closed"))

// Not delegable: avoid inside the Filter
//   Year(DueDate) = 2026      Month(DueDate) = 11      Text(DueDate, "yyyy-mm") = "2026-11"
//   DateDiff(DueDate, Today()) > 5

