  Loop only the matches: Apply to each over body('Filter_array')

// UTC to a named time zone, formatted
convertFromUtc(triggerBody()?['Created'], 'GMT Standard Time', 'dd MMM yyyy HH:mm')

// Between any two zones
convertTimeZone(triggerBody()?['StartTime'], 'UTC', 'Eastern Standard Time', 'yyyy-MM-dd HH:mm')

// Local "now" and "today"
convertFromUtc(utcNow(), 'W. Europe Standard Time', 'yyyy-MM-dd HH:mm')
convertFromUtc(utcNow(), 'W. Europe Standard Time', 'yyyy-MM-dd')

// Empty-safe formatting
if(
  empty(triggerBody()?['DueDate']),
  'No due date',
  formatDateTime(triggerBody()?['DueDate'], 'dd MMM yyyy')
)

// Common format strings
//   'yyyy-MM-dd'            2026-11-20
//   'dd/MM/yyyy'            20/11/2026
//   'dddd d MMMM yyyy'      Friday 20 November 2026
//   'HH:mm'                 14:05     (24-hour)
//   'h:mm tt'               2:05 PM

// Is the due date before today (local)?
less(
  formatDateTime(triggerBody()?['DueDate'], 'yyyy-MM-dd'),
  convertFromUtc(utcNow(), 'GMT Standard Time', 'yyyy-MM-dd')
)

// Days between two dates
div(sub(ticks(triggerBody()?['DueDate']), ticks(utcNow())), 864000000000)

// Local time back to UTC for a filter query
convertToUtc('2026-11-20T09:00:00', 'GMT Standard Time')

// Safe property access: ? returns null instead of failing
triggerBody()?['Manager']?['Email']

