coalesce(triggerBody()?['PreferredName'], triggerBody()?['DisplayName'], 'there')

// Null or empty string or empty array
empty(triggerBody()?['Comments'])

// Default when null OR empty text
if(empty(triggerBody()?['Comments']), 'No comments', triggerBody()?['Comments'])

// Safe number conversion
int(coalesce(triggerBody()?['Quantity'], 0))
float(if(empty(triggerBody()?['Amount']), '0', string(triggerBody()?['Amount'])))

// Safe text functions
toLower(coalesce(triggerBody()?['Category'], ''))
length(coalesce(body('Get_items')?['value'], json('[]')))

// Condition: is the field null?
equals(triggerBody()?['DueDate'], null)

