  // Date and time (the fraction is the time of day)
  addSeconds(
    '1899-12-30',
    int(mul(float(item()?['StartDateTime']), 86400)),
    'yyyy-MM-ddTHH:mm:ss'
  )

  // Empty-safe
  if(
    empty(item()?['StartDate']),
    null,
    addDays('1899-12-30', int(item()?['StartDate']), 'yyyy-MM-dd')
  )

  // Handles both serial numbers and text dates in the same column
  if(
    isFloat(string(item()?['StartDate'])),
    addDays('1899-12-30', int(float(item()?['StartDate'])), 'yyyy-MM-dd'),
    formatDateTime(item()?['StartDate'], 'yyyy-MM-dd')
